def split_bill(total, people, tip_percent=0):
    if total < 0 or people <= 0 or tip_percent < 0:
        raise ValueError("Invalid bill values")
    return total * (1 + tip_percent / 100) / people

try:
    total = float(input("Total: "))
    people = int(input("People: "))
    tip = float(input("Tip percentage: "))
    share = split_bill(total, people, tip)
    print(f"Each pays: {share:.2f}")
except ValueError:
    print("Invalid bill input")
